onst float2 e0 = *reinterpret_cast<const float2*>(emb + row_base); const float2 e1 = *reinterpret_cast<const float2*>(emb + row_base + 18); const float2 e2 = *reinterpret_cast<const float2*>(emb + row_base + 36); const float2 e3 = *reinterpret_cast<const float2*>(emb + row_base + 54); float s0x, c0x, s0y, c0y; float s1x, c1x, s1y, c1y; float s2x, c2x, s2y, c2y; float s3x, c3x, s3y, c3y; __sincosf(e0.x, &s0x, &c0x); __sincosf(e0.y, &s0y, &c0y); __sincosf(e1.x, &s1x, &c1x); __sincosf(e1.y, &s1y, &c1y); __sincosf(e2.x, &s2x, &c2x); __sincosf(e2.y, &s2y, &c2y); __sincosf(e3.x, &s3x, &c3x); __sincosf(e3.y, &s3y, &c3y); float h0 = fmaf(gs0.x, c0x, -gc0.x * s0x); h0 = fmaf(gs2.x, c2x, h0 - gc2.x * s2x); float w0 = fmaf(gs1.x, c1x, -gc1.x * s1x); w0 = fmaf(gs3.x, c3x, w0 - gc3.x * s3x); acc0 = fmaf(pos_h, h0, acc0); acc0 = fmaf(pos_w, w0, acc0); float h1 = fmaf(gs0.y, c0y, -gc0.y * s0y); h1 = fmaf(gs2.y, c2y, h1 - gc2.y * s2y); float w1 = fmaf(gs1.y, c1y, -gc1.y * s1y); w1 = fmaf(gs3.y, c3y, w1 - gc3.y * s3y); acc1 = fmaf(pos_h, h1, acc1); acc1 = fmaf(pos_w, w1, acc1); } acc0 = warp_reduce_sum(acc0); acc1 = warp_reduce_sum(acc1); if (lane == 0) { warp_sums0[warp] = acc0; warp_sums1[warp] = acc1; } __syncthreads(); if (warp == 0) { float sum0 = lane < kWarpsPerBlock ? warp_sums0[lane] : 0.0f; float sum1 = lane < kWarpsPerBlock ? warp_sums1[lane] : 0.0f; sum0 = warp_reduce_sum(sum0); sum1 = warp_reduce_sum(sum1); if (lane == 0) { workspace[(k0 + 0) * kMaxSplits + split] = sum0; workspace[(k0 + 1) * kMaxSplits + split] = sum1; } } } __global__ __launch_bounds__(32, 1) void finalize_pair_kernel( const float* __restrict__ workspace, const int num_splits, float* __restrict__ grad_inv_freq) { const int pair = blockIdx.x; const int lane = threadIdx.x & 31; const int k0 = pair * 2; float acc0 = lane < num_splits ? workspace[(k0 + 0) * kMaxSplits + lane] : 0.0f; float acc1 = lane < num_splits ? workspace[(k0 + 1) * kMaxSplits + lane] : 0.0f; acc0 = warp_reduce_sum(acc0); acc1 = warp_