rg; g_state.final_args[2] = &g_state.out_arg; g_state.final_params.kernelParams = g_state.final_args; return cudaGraphExecKernelNodeSetParams(g_state.exec, g_state.final_node, &g_state.final_params) == cudaSuccess; } bool build_graph( const torch::Tensor& grad_cos, const torch::Tensor& grad_sin, const torch::Tensor& pos_ids, const torch::Tensor& emb, const torch::Tensor& grad_inv_freq) { reset_graph_state(); g_state.device_index = grad_cos.get_device(); g_state.workspace = torch::empty({kWorkspaceElems}, grad_cos.options()); g_state.workspace_arg = g_state.workspace.data_ptr<float>(); g_state.grad_cos_arg = grad_cos.data_ptr<float>(); g_state.grad_sin_arg = grad_sin.data_ptr<float>(); g_state.pos_ids_arg = pos_ids.data_ptr<int64_t>(); g_state.emb_arg = emb.data_ptr<float>(); g_state.total_patches_arg = grad_cos.size(0); g_state.num_splits_arg = select_num_splits(g_state.total_patches_arg); g_state.out_arg = grad_inv_freq.data_ptr<float>(); g_state.partial_params.func = reinterpret_cast<void*>(splitk_pair_kernel); g_state.partial_params.gridDim = dim3(kPairs, g_state.num_splits_arg, 1); g_state.partial_params.blockDim = dim3(kThreads, 1, 1); g_state.partial_params.sharedMemBytes = 0; g_state.partial_params.extra = nullptr; g_state.partial_args[0] = &g_state.grad_cos_arg; g_state.partial_args[1] = &g_state.grad_sin_arg; g_state.partial_args[2] = &g_state.pos_ids_arg; g_state.partial_args[3] = &g_state.emb_arg; g_state.partial_args[4] = &g_state.total_patches_arg; g_state.partial_args[5] = &g_state.num_splits_arg; g_state.partial_args[6] = &g_state.workspace_arg; g_state.partial_params.kernelParams = g_state.partial_args; g_state.final_params.func = reinterpret_cast<void*>(finalize_pair_kernel); g_state.final_params.gridDim = dim3(kPairs, 1, 1); g_state.final_params.blockDim = dim3(32, 1, 1); g_state.final_params.sharedMemBytes = 0; g_state.final_params.extra = nullptr; g_state.final_args[0] = &g_state.workspace_arg; g_state.final_args[1] = &g_state.num_splits_arg; g_state.final_args[2] = &g_state.out_arg; g_state.final_params.kernelParams = g_state.final_args; if (cudaGraphCreate(&g_state.graph, 0) != cudaSuccess) { reset_graph_state(); return false; } if (cudaGraphAddKernelNode(&g_state.partial_node, g_state.graph, nullptr, 0, &g_state.partial_params) != cudaSuccess) { reset_graph_state(); return false; } if (cudaGraphAddKernelNode(&g_state.final_node, g_state.graph, &g_state.partial_node, 1, &g_state.final_params) != cudaSuccess) { reset_graph_state(); return false; } if (cudaGraphInstantiate(&g_state.exec, g_state.graph, nullptr, nullptr, 0) != cudaSuccess) { reset_graph_state(); return false; } set_cached_ptrs(grad_cos, grad_sin, pos_ids, emb, grad_inv_freq); g_state.ready = true; return true; } inline bool graph_exact_match( const torch::Tensor& grad_cos, const torch::Tensor& grad_sin, const torch::Tensor& pos_ids, const torch::Tensor& emb, const torch::Tensor& grad_inv_freq) { return g_state.ready && grad_cos.data_ptr() == g_state.grad_cos_ptr && grad_sin.data_ptr() == g_state.grad_sin_ptr && pos_ids.data_ptr() == g_state.pos_ids_ptr && emb.data_ptr() == g_state.emb_ptr && grad_inv_freq.data_ptr() == g_state.out_ptr && grad_cos.size(0) == g_state.total_patches; } inline bool graph_quick_shape_match( const torch::Tensor& grad_cos, const torch::Tensor& grad_sin, const torch::Tensor& pos_ids, const torch::Tensor& inv_freq, const torch::Tensor& emb, const torch::Tensor& grad_inv_freq) { return g_state.ready && grad_cos.dim() == 2 && grad_sin.dim() == 2 && pos_ids.dim() == 2 && inv_freq.dim() == 1 && emb.dim() == 2 && grad_inv_freq.dim() == 1 && grad_cos.size(0) == grad_sin.size(0) && grad_cos.size(0) == pos_ids.size(0) && grad_cos.size(0) == emb.size(0) && grad_cos.size(1) == kHeadDim && grad_sin.size(1) == kHeadDim && emb.size(1) == kHeadDim && pos_ids.size(1) == 2 && inv_freq.size(0) == kQuarter && grad_inv_freq.size(0) == kQuarter && grad_cos.get_device() == g_state.device_index && grad_cos.get_device() == grad_sin.get_devi